import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, smoothstep, min, sub, step } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @typedef {Object} NodeContext
 */

/**
 * Create a gradient CTA button node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container
  const root = new Group();

  // ------------------------------
  // Button geometry & material
  // ------------------------------
  const btnWidth = 2.6;
  const btnHeight = 0.68;
  const btnDepth = 0.03;

  const geometry = new BoxGeometry(btnWidth, btnHeight, btnDepth);

  // Gradient color node (vertical)
  const uvNode = uv();

  const gradColor = mix(
    mix(
      color('#ff4450'),
      color('#ff2a38'),
      smoothstep(0.0, 0.55, uvNode.y)
    ),
    color('#c1121f'),
    smoothstep(0.55, 1.0, uvNode.y)
  );

  // Perimeter emissive (simple approximation)
  const edgeDist = min(
    min(uvNode.x, sub(1.0, uvNode.x)),
    min(uvNode.y, sub(1.0, uvNode.y))
  );
  const borderMask = step(edgeDist, 0.015);
  const emissiveColor = mix(
    color('#000000'),
    color('#ff2a38'),
    borderMask
  );

  const material = new MeshStandardNodeMaterial();
  material.colorNode = gradColor;
  material.emissiveNode = emissiveColor;
  material.roughness = 0.5;
  material.metalness = 0.35;
  material.clearcoat = 0.22;
  material.clearcoatRoughness = 0.0;

  const buttonMesh = new Mesh(geometry, material);
  buttonMesh.position.set(0, 0, 0);
  root.add(buttonMesh);

  // ------------------------------
  // Contact shadow plane
  // ------------------------------
  const shadowGeom = new PlaneGeometry(btnWidth, btnHeight);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = color(0.35);
  shadowMat.transparent = true;

  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -btnDepth / 2 - 0.04, 0);
  root.add(shadowMesh);

  // ------------------------------
  // Text label (CTA)
  // ------------------------------
  const labelOpts = {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: 0.08 * 20, // pixels approximation
  };
  const label = ctx.fontAtlas.createText('BEGIN COMMISSION', labelOpts);
  label.position.set(0, 0, btnDepth / 2 + 0.001);
  root.add(label);

  // ------------------------------
  // Caption text
  // ------------------------------
  const captionOpts = {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacing: 0.12 * 9,
  };
  const caption = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', captionOpts);
  const captionY = -btnHeight / 2 - 0.25;
  caption.position.set(0, captionY, -0.001);
  root.add(caption);

  // ------------------------------
  // Entrance animation (weighted settle)
  // ------------------------------
  const settleTL = gsap.timeline({ paused: false });
  settleTL.from(
    root.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    },
    0
  );

  // ------------------------------
  // Interaction handlers (optional)
  // ------------------------------
  const handlers = {
    hoverEnter: () => {
      gsap.to(root.position, {
        z: 0.06,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      // increase emissive intensity (approximate by brightening emissive color)
      material.emissiveIntensity = 2.2;
    },
    hoverLeave: () => {
      gsap.to(root.position, {
        z: 0,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      material.emissiveIntensity = 1.6;
    },
    pressDown: () => {
      gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      // deepen chamfer shadow (placeholder – not implemented)
    },
    pressUp: () => {
      gsap.to(root.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    },
  };
  root.userData.handlers = handlers;

  // ------------------------------
  // Cleanup routine
  // ------------------------------
  root.userData.cleanup = () => {
    settleTL.kill();
    // Dispose geometries & materials
    geometry.dispose();
    material.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    // Remove children
    root.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
  };

  return root;
}
